const d2we3Tbl = table(['Step', 'Work'], [['Given equation', r`$x^2 - 4x + 2 = 0$: $S = 4$, $P = 2$`], ['New sum', r`$\alpha^3 + \beta^3 = S^3 - 3PS = 64 - 24 = 40$`], ['New product', r`$\alpha^3\beta^3 = P^3 = 8$`], ['Equation', '$x^2 - 40x + 8 = 0$']], 'Worked example 3 table of Part 2: for x squared minus 4x plus 2, the cubes of the roots have sum 64 minus 24 equal to 40 and product 8, so the new equation is x squared minus 40 x plus 8 equal to zero.', 'Cubes: sum $S^3 - 3PS$, product $P^3$.');
// d2 we4: roots alpha + 1/beta, beta + 1/alpha for x^2 - 3x + 1
{
  const q = quad(1, -3, 1);
  const a1 = eadd(q.r1, einv(q.r2, q.d)), b1 = eadd(q.r2, einv(q.r1, q.d));
  must(ezero(polyAt([1, -6, 4], a1, q.d)) && ezero(polyAt([1, -6, 4], b1, q.d)) && 3 + 3 / 1 === 6 && 1 + 2 + 1 === 4, 'd2 we4');
}
const d2we4Tbl = table(['Step', 'Work'], [['Given equation', r`$x^2 - 3x + 1 = 0$: $S = 3$, $P = 1$`], ['New sum', r`$\left(\alpha + \dfrac{1}{\beta}\right) + \left(\beta + \dfrac{1}{\alpha}\right) = S + \dfrac{S}{P} = 3 + 3 = 6$`], ['New product', r`$\left(\alpha + \dfrac{1}{\beta}\right)\left(\beta + \dfrac{1}{\alpha}\right) = P + 2 + \dfrac{1}{P} = 1 + 2 + 1 = 4$`], ['Equation', '$x^2 - 6x + 4 = 0$']], 'Worked example 4 table of Part 2: for x squared minus 3x plus 1, the new roots alpha plus 1 over beta and beta plus 1 over alpha have sum 6 and product 4, so the equation is x squared minus 6x plus 4 equal to zero.', 'Expand the product carefully: four terms.');
const commonFlow = flow('LR', [['a', 'Two quadratics with a common root $x_0$'], ['b', 'Eliminate $x^2$ by subtracting multiples'], ['c', 'Solve the linear equation for $x_0$'], ['d', 'Substitute $x_0$ into either equation']], [['a', 'b'], ['b', 'c'], ['c', 'd']], 'Flow for common roots: take two quadratics sharing a root, eliminate x squared by subtracting suitable multiples, solve the resulting linear equation for the common root, then substitute it into either equation to find the unknown.', 'Common root: eliminate, solve, substitute.');
// common root condition and example
{
  const cond = (a1, b1, c1, a2, b2, c2) => (c1 * a2 - c2 * a1) ** 2 === (a1 * b2 - a2 * b1) * (b1 * c2 - b2 * c1);
  must(cond(1, -3, -10, 2, -7, -15) && !cond(1, -3, -10, 1, 4, 1) && hasRoots([1, -3, -10], [fr(5), fr(-2)]) && hasRoots([2, -7, -15], [fr(5), fr(-3, 2)]) && 2 * 1 * -10 + 0 === -20 && isRoot([1, -3, -10], 5, 0, 1) && isRoot([2, -7, -15], 5, 0, 1), 'common roots example');
  must(range(-30, 30).every((k) => cond(1, 2, k, 1, k, 2) === (k === 2 || k === -3)), 'condition formula against s305');
}
const d2we5Tbl = table(['Step', 'Work'], [['Equations', '$x^2 - 3x - 10 = 0$ and $2x^2 - 7x - 15 = 0$'], ['Eliminate $x^2$', '$2 \\times (\\text{first}) - (\\text{second})$: $-6x - 20 + 7x + 15 = 0$'], ['Linear equation', '$x - 5 = 0$, so the common root is $x = 5$'], ['Check', '$25 - 15 - 10 = 0$ and $50 - 35 - 15 = 0$']], 'Worked example 5 table of Part 2: for x squared minus 3x minus 10 and 2 x squared minus 7x minus 15, doubling the first and subtracting the second gives x minus 5 equal to zero, so the common root is 5, which both equations satisfy.', 'The other roots, $-2$ and $-\\dfrac{3}{2}$, are not shared.');
const condFlow = table(['Two quadratics $a_1x^2 + b_1x + c_1$ and $a_2x^2 + b_2x + c_2$', 'Condition for exactly one common root'], [['General', '$(c_1a_2 - c_2a_1)^2 = (a_1b_2 - a_2b_1)(b_1c_2 - b_2c_1)$'], ['Both roots common', 'the coefficients are in proportion: $\\dfrac{a_1}{a_2} = \\dfrac{b_1}{b_2} = \\dfrac{c_1}{c_2}$']], 'Table of conditions for common roots: one common root needs the elimination relation (c1 a2 minus c2 a1) squared equals (a1 b2 minus a2 b1) times (b1 c2 minus b2 c1); both roots common needs the coefficients in proportion.', 'The relation also holds when both roots are common, so test the proportion separately.');
// quadratic functions
const pPar = plot({ x: [-1, 5], y: [-4, 6], fns: [{ expr: 'x^2 - 4x + 1', label: '$y = x^2 - 4x + 1$' }, { expr: '4x - x^2', label: '$y = -x^2 + 4x$' }], pts: [[2, -3, '(2, -3)'], [2, 4, '(2, 4)'], [0, 1, '(0, 1)'], [0, 0, '(0, 0)'], [4, 0, '(4, 0)']] }, 'Two parabolas sharing the axis x equal to 2. The upward one, y equal to x squared minus 4x plus 1, has lowest point (2, minus 3) and meets the y-axis at 1. The downward one, y equal to minus x squared plus 4x, has highest point (2, 4) and passes through the origin and (4, 0).', 'Upward: least value at the vertex. Downward: greatest value at the vertex.');
must(qval(1, -4, 1, fr(2)).n === -3 && feq(vertex(1, -4, 1).y, fr(-3)) && feq(vertex(-1, 4, 0).y, fr(4)) && xs.every((x) => near(-x * x + 4 * x, 4 * x - x * x)) && hasRoots([-1, 4, 0], [fr(0), fr(4)]), 'parabola figure');
const signTbl = table(['', '$D > 0$', '$D = 0$', '$D < 0$'], [['$a > 0$', 'negative between the roots, positive outside', 'non-negative; zero only at the root', 'positive for all real $x$'], ['$a < 0$', 'positive between the roots, negative outside', 'non-positive; zero only at the root', 'negative for all real $x$']], 'Table of the sign of a x squared plus b x plus c: with a positive and two real roots the expression is negative between them and positive outside; with a negative the pattern reverses; with D zero it never changes sign and touches zero once; with D negative it keeps the sign of a for every real x.', 'The sign of $a$ and the sign of $D$ decide everything.');
must(xs.every((x) => (x * x - 4 * x + 3 < 0) === (x > 1 && x < 3)) && xs.every((x) => (-(x * x) + 4 * x - 3 > 0) === (x > 1 && x < 3)) && xs.every((x) => x * x - 4 * x + 7 > 0 && -x * x + 4 * x - 7 < 0 && x * x - 4 * x + 4 >= 0 && -(x * x) + 4 * x - 4 <= 0), 'sign table');
// d2 we6: f = -3x^2 + 12x - 7
{
  const v = vertex(-3, 12, -7);
  must(feq(v.x, fr(2)) && feq(v.y, fr(5)) && qval(-3, 12, -7, fr(0)).n === -7 && xs.every((x) => near(-3 * x * x + 12 * x - 7, -3 * (x - 2) ** 2 + 5)) && disc(-3, 12, -7) === 60, 'we6d2');
}
const pF = plot({ x: [-1, 5], y: [-20, 8], fns: [{ expr: '12x - 3x^2 - 7', label: '$y = -3x^2 + 12x - 7$' }], pts: [[2, 5, '(2, 5)'], [0, -7, '(0, -7)']] }, 'Graph of y equal to minus 3 x squared plus 12 x minus 7: a downward parabola with highest point (2, 5) and y-intercept minus 7. It meets the x-axis twice, at about 0.71 and 3.29.', 'Highest point $(2, 5)$; the $x$-intercepts are irrational.');
const d2we6Tbl = table(['Step', 'Work'], [['Complete the square', '$-3x^2 + 12x - 7 = -3(x - 2)^2 + 5$'], ['Greatest value', '$5$, at $x = 2$ (since $-3(x - 2)^2 \\le 0$)'], ['Axes', r`$y$-intercept $-7$; $D = 144 - 84 = 60 > 0$, so two $x$-intercepts $2 \pm \dfrac{\sqrt{15}}{3}$`], ['Sign', 'positive only between the two roots']], 'Worked example 6 table of Part 2: minus 3 x squared plus 12 x minus 7 equals minus 3 times x minus 2 squared plus 5, so the greatest value is 5 at x equal to 2; the discriminant is 60, so there are two x-intercepts, and the function is positive only between them.', 'Complete the square to see the extreme value at once.');
must(isRoot([3, -12, 7], fr(2), fr(1, 3), 15) && isRoot([3, -12, 7], fr(2), fr(-1, 3), 15), 'we6d2 roots');
// d2 we7: fence A = x(18 - x)
{
  const A = (x) => x * (18 - x);
  must(A(9) === 81 && A(0) === 0 && A(18) === 0 && xs.every((x) => A(x) <= 81 + 1e-12) && [8.5, 9.5, 5, 12].every((x) => A(x) < 81), 'fence');
}
const pA = plot({ x: [-2, 20], y: [-30, 90], fns: [{ expr: '18x - x^2', label: '$A = x(18 - x)$' }], pts: [[0, 0, '(0, 0)'], [18, 0, '(18, 0)'], [9, 81, '(9, 81)']] }, 'Graph of A equal to x times 18 minus x: a downward parabola through (0, 0) and (18, 0) with highest point (9, 81), showing that a width of 9 gives the largest area.', 'Width $9$ m gives the largest area, $81$ m$^2$.');
const d2we7Tbl = table(['Step', 'Work'], [['Model', 'width $x$, length $18 - x$ (half of $36$ m of wire): $A = x(18 - x)$'], ['Standard form', '$A = -x^2 + 18x$, with $a = -1 < 0$'], ['Greatest value', 'at $x = -\\dfrac{18}{2(-1)} = 9$: $A = 9 \\times 9 = 81$'], ['Meaning', 'a $9$ m by $9$ m square gives $81$ m$^2$']], 'Worked example 7 table of Part 2: a rectangle fenced with 36 metres of wire has area x times 18 minus x; the greatest area is at x equal to 9, where it is 81 square metres, so the square is best.', 'Half the perimeter gives the length plus the width.');
const summary2 = flow('LR', [['a', r`Equation from roots: $x^2 - Sx + P = 0$`], ['b', r`Symmetric functions reduce to $S$ and $P$`], ['c', 'Common root: eliminate, solve, substitute'], ['d', r`Vertex $x = -\dfrac{b}{2a}$: greatest value if $a < 0$, least if $a > 0$`]], [['a', 'b'], ['b', 'c'], ['c', 'd']], 'Summary flow of Part 2: form an equation from sum and product, reduce symmetric functions to sum and product, find a common root by eliminating and substituting, and use the vertex for the greatest value when a is negative or the least value when a is positive.', 'Part 2 in one line.');
const tips2 = table(['Question type', 'How ISC marks are usually given'], [['Form an equation (2)', 'sum and product 1, equation 1'], ['Roots as functions of $\\alpha, \\beta$ (3)', 'original $S$ and $P$ 1, new sum and product 1, equation 1'], ['Common root (3)', 'elimination 1, common root 1, value of the unknown 1'], ['Extreme value or graph (3)', 'vertex 1, value 1, intercepts or sign statement 1']], 'Exam tips table for Part 2: forming an equation earns the sum and product then the equation; functions of the roots earn the original sum and product, the new sum and product and the equation; common roots earn the elimination, the root and the unknown; extreme values and graphs earn the vertex, the value and the intercepts or sign.', 'Write $S$ and $P$ down before using them.');

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Quadratic Equations - Part 1: Solving, reducible equations and nature of roots',
  goals: ['Solve a quadratic equation with real or complex roots by the formula', 'Solve equations reducible to quadratic form by a substitution', 'Use the discriminant to decide the nature of the roots', 'Use the sum and product of the roots to meet root conditions'],
  slides: [
    sl('title', 'Quadratic Equations, Part 1', { b: 'Every root, real or not, and what the coefficients say about it.', v: route1, n: 'Welcome to the chapter on quadratic equations. In class ten you solved them when the roots were real. Now we meet roots that are not real, use the discriminant to predict the kind of roots, and solve harder equations by turning them into quadratics.' }),
    sl('concept', 'How many roots? The fundamental theorem', { b: r`**Fundamental theorem of algebra (statement):** every polynomial equation of degree $n \ge 1$ with complex coefficients has at least one complex root. Hence it has exactly $n$ roots in $\mathbb{C}$, counted with multiplicity.`, v: ftaTbl, n: 'The fundamental theorem says that an equation of degree n has at least one complex root, and so exactly n complex roots when repeated roots are counted repeatedly. A quadratic always has two roots, but they may be repeated or not real. We state the theorem without proof.' }),
    sl('check', 'Quick check: the theorem', { b: 'Pick the correct statement of the theorem.', chk: 'm18', n: 'Remember that the roots are complex numbers, counted with multiplicity.' }),
    sl('concept', 'The quadratic formula', { b: r`For $ax^2 + bx + c = 0$ with $a \ne 0$: $x = \dfrac{-b \pm \sqrt{D}}{2a}$, where $D = b^2 - 4ac$ is the **discriminant**. If $D < 0$, write $\sqrt{D} = i\sqrt{-D}$.`, v: formulaFlow, n: 'Divide the equation by a, complete the square, and take square roots. The result is the quadratic formula with minus b plus or minus the square root of the discriminant, all over two a. When the discriminant is negative, its square root is i times the square root of the positive number minus D.' }),
    sl('example', 'Worked example 1: irrational roots', { b: r`Solve $3x^2 - 4x - 5 = 0$.`, ul: ['$D = 16 + 60 = 76$', r`$\sqrt{76} = 2\sqrt{19}$`, r`$x = \dfrac{2 \pm \sqrt{19}}{3}$`], v: we1Tbl, n: 'Here a is three, b is minus four and c is minus five. The discriminant is sixteen plus sixty, which is seventy six. Its square root is two times the square root of nineteen. The formula gives four plus or minus two root nineteen over six, and cancelling two leaves two plus or minus root nineteen over three.' }),
    sl('diagram', 'Cut, touch or miss: the three cases', { b: r`The sign of $D$ tells how the parabola meets the $x$-axis: it **cuts** it twice, **touches** it once, or **misses** it.`, v: pCases, n: 'Here are three parabolas of the same shape. With a positive discriminant the curve crosses the horizontal axis at two points. With zero discriminant it just touches the axis at its lowest point. With a negative discriminant it floats above the axis, so there is no real root, but there are two complex ones.' }),
    sl('concept', 'Nature of the roots', { b: r`For real coefficients, $D$ decides the kind of root. If the coefficients are rational and $D$ is a perfect square, the roots are rational.`, v: natureTbl, n: 'Read the discriminant before you solve. Positive and a perfect square means two different rational roots. Positive but not a perfect square means two different irrational roots. Zero means two equal real roots. Negative means two non-real roots which are conjugates of each other.' }),
    sl('example', 'Worked example 2: complex roots', { b: r`Solve $3x^2 - 2x + 7 = 0$ in $\mathbb{C}$.`, ul: ['$D = 4 - 84 = -80$', r`$\sqrt{-80} = 4i\sqrt{5}$`, r`$x = \dfrac{1 \pm 2i\sqrt{5}}{3}$`], v: we2Tbl, n: 'The discriminant is four minus eighty four, which is minus eighty. The square root of minus eighty is i times the square root of eighty, and eighty is sixteen times five, so it is four i root five. Dividing by six, the roots are one plus or minus two i root five, over three.' }),
    sl('concept', 'Conjugate pairs', { b: 'With **real** coefficients, non-real roots come in conjugate pairs. With **rational** coefficients, so do roots of the form $m \\pm \\sqrt{n}$. Real coefficients alone do **not** force surd pairs.', v: conjTbl, n: 'If the coefficients are real, a non-real root always arrives with its conjugate. If the coefficients are rational, a root like two plus root three always arrives with two minus root three. But with merely real coefficients, the partner of two plus root three can be a completely different number, as the last row shows.' }),
    sl('check', 'Quick check: how many non-real roots?', { b: 'Decide whether a real quadratic can have exactly one non-real root.', chk: 'tf1', n: 'Think about conjugate pairs.' }),
    sl('concept', 'Equations reducible to quadratic form', { b: 'If one expression repeats, give it a new letter. Solve the quadratic in that letter, then return to $x$.', v: redTbl, n: 'Some equations of higher degree are quadratics in disguise. A quartic with only even powers is a quadratic in x squared. A repeated bracket becomes a new letter. And an equation that reads the same forwards and backwards is a quadratic in x plus one over x. Always return to x at the end.' }),
    sl('example', 'Worked example 3: a quartic in $x^2$', { b: r`Solve $x^4 + 2x^2 - 15 = 0$.`, ul: ['$y = x^2$: $y^2 + 2y - 15 = 0$', '$y = 3$ or $y = -5$', r`$x = \pm\sqrt{3}$ or $x = \pm i\sqrt{5}$`], v: we3Tbl, n: 'Put y equal to x squared. The equation becomes y squared plus two y minus fifteen, which factorises as y plus five times y minus three. So y is three or minus five. Then x squared equals three gives plus or minus root three, and x squared equals minus five gives plus or minus i root five.' }),
    sl('check', 'Quick check: the second value of $y$', { b: 'Complete the substitution for a quartic with even powers only.', chk: 'fb4', n: 'Factorise the quadratic in y.' }),
    sl('example', 'Worked example 4: using $y = x + \\dfrac{1}{x}$', { b: r`Solve $3\left(x^2 + \dfrac{1}{x^2}\right) - 16\left(x + \dfrac{1}{x}\right) + 26 = 0$.`, ul: [r`$x^2 + \dfrac{1}{x^2} = y^2 - 2$, so $3y^2 - 16y + 20 = 0$`, r`$y = 2$ or $y = \dfrac{10}{3}$`, r`$x = 1$ (twice), $3$ or $\dfrac{1}{3}$`], v: we4Tbl, n: 'Replace x plus one over x by y. Then x squared plus one over x squared is y squared minus two. The equation becomes three y squared minus sixteen y plus twenty, so y is two or ten thirds. For y equal to two we get x equal to one, twice. For ten thirds we get three or one third.' }),
    sl('concept', 'Sum and product of the roots', { b: r`If $\alpha, \beta$ are the roots of $ax^2 + bx + c = 0$: $\alpha + \beta = -\dfrac{b}{a}$ and $\alpha\beta = \dfrac{c}{a}$.`, v: spFlow, n: 'Add the two roots from the formula and the square roots cancel, leaving minus b over a. Multiply them and you get b squared minus the discriminant over four a squared, which simplifies to c over a. So the sum and product of the roots can be read off without solving.' }),
    sl('check', 'Quick check: a sum', { b: 'Read the sum of the roots from the coefficients.', chk: 'fb1', n: 'Use minus b over a.' }),
    sl('concept', 'Special root conditions', { b: r`Conditions on $a, b, c$ for roots that are equal, reciprocal, equal and opposite, zero, in the ratio $2:1$, or one the square of the other.`, v: condTbl, n: 'Each special property of the roots turns into a relation between the coefficients. Equal roots: b squared equals four a c. Reciprocal roots: c equals a. Equal and opposite: b is zero. One root zero: c is zero. One root twice the other: two b squared equals nine a c. And one root the square of the other has the longer relation in the last row.' }),
    sl('example', 'Worked example 5: reciprocal roots', { b: r`Find $m$ so that the roots of $2x^2 - (3m - 1)x + (m + 5) = 0$ are reciprocals of each other, and check that the roots are real.`, ul: ['Product $= \\dfrac{m + 5}{2} = 1$, so $m = -3$', '$2x^2 + 10x + 2 = 0$', '$D = 100 - 16 = 84 > 0$'], v: we5Tbl, n: 'Reciprocal roots have product one. The product here is m plus five over two, so m plus five equals two and m is minus three. The equation becomes two x squared plus ten x plus two. Its discriminant is eighty four, positive, so the roots are real and their product is one.' }),
    sl('example', 'Worked example 6: one root the square of the other', { b: r`One root of $x^2 - 12x + k = 0$ is the square of the other. Find $k$.`, ul: ['Use $ac^2 + a^2c + b^3 = 3abc$ with $a = 1$, $b = -12$, $c = k$', '$k^2 + 37k - 1728 = 0$', '$k = 27$ or $k = -64$'], v: we6Tbl, n: 'Put a equal to one, b equal to minus twelve and c equal to k in the long condition. After simplifying we get k squared plus thirty seven k minus one thousand seven hundred twenty eight equals zero. Its discriminant is a perfect square, so k is twenty seven, with roots three and nine, or minus sixty four, with roots minus four and sixteen.' }),
    sl('summary', 'Summary', { ul: ['$D$ gives the nature of the roots', 'Real coefficients: non-real roots in conjugate pairs', 'Substitute to reduce an equation to a quadratic, then return to $x$', r`$\alpha + \beta = -\dfrac{b}{a}$, $\alpha\beta = \dfrac{c}{a}$ and the six root conditions`], v: summary1, n: 'To sum up. The discriminant gives the nature of the roots. Real coefficients give conjugate pairs of non-real roots. A substitution turns many equations into quadratics, and you must return to x at the end. And the sum and product of the roots give every special condition without solving the equation.' }),
    sl('exam-tips', 'Exam tips', { ul: ['Write $D$ first and state the kind of roots', 'After a substitution, solve for **every** root in $x$', 'For a condition on $k$, check that the roots are real if needed', 'Do not assume $m - \\sqrt{n}$ is a root unless the coefficients are rational'], v: tips1, n: 'In the examination, write the discriminant first and name the kind of roots. After a substitution, convert every value of the new letter back into x. If a condition on k also needs real roots, check the discriminant. And only assume a surd partner when the coefficients are rational.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2,
  title: 'Quadratic Equations - Part 2: Forming equations, common roots and quadratic functions',
  goals: ['Form a quadratic equation from its roots', 'Evaluate symmetric functions of the roots without solving', 'Form an equation whose roots are functions of the roots of another', 'Find a common root of two equations', 'Find the sign, graph and extreme value of a quadratic function'],
  slides: [
    sl('title', 'Quadratic Equations, Part 2', { b: 'Build equations from roots, share roots, and read the shape of the parabola.', v: route2, n: 'Welcome to part two. Part one went from equations to roots. Now we go the other way and build equations from roots, work with expressions in the roots without solving, find roots shared by two equations, and then study the parabola itself.' }),
    sl('concept', 'Forming an equation from its roots', { b: r`If the roots are $\alpha$ and $\beta$, the equation is $x^2 - (\alpha + \beta)x + \alpha\beta = 0$; multiply by a number to clear fractions.`, v: formTbl, n: 'An equation with roots alpha and beta can be written as x minus alpha times x minus beta equals zero. Expanding gives x squared minus the sum times x plus the product. So find the sum and the product, write the equation, and multiply through if there are fractions.' }),
    sl('example', 'Worked example 1: fractional roots', { b: r`Form the equation with integer coefficients whose roots are $\dfrac{3}{4}$ and $-\dfrac{5}{2}$.`, ul: [r`Sum $= -\dfrac{7}{4}$, product $= -\dfrac{15}{8}$`, r`$x^2 + \dfrac{7}{4}x - \dfrac{15}{8} = 0$`, '$8x^2 + 14x - 15 = 0$'], v: d2we1Tbl, n: 'Three quarters plus minus five halves is minus seven quarters. Three quarters times minus five halves is minus fifteen eighths. So the equation is x squared plus seven quarters x minus fifteen eighths equals zero. Multiplying by eight clears the fractions and gives eight x squared plus fourteen x minus fifteen.' }),
    sl('concept', 'Symmetric functions of the roots', { b: r`An expression that does not change when $\alpha$ and $\beta$ are swapped can be written with $S = \alpha + \beta$ and $P = \alpha\beta$.`, v: symTbl, n: 'An expression is symmetric if swapping alpha and beta leaves it unchanged. Every such expression can be written using the sum S and the product P. The table lists the ones you need: the sum of squares, the sum of cubes, the square of the difference, the reciprocals, and the ratio sum.' }),
    sl('example', 'Worked example 2: squares and cubes', { b: r`For $3x^2 - 5x - 7 = 0$ find $\alpha^2 + \beta^2$ and $\alpha^3 + \beta^3$.`, ul: [r`$S = \dfrac{5}{3}$, $P = -\dfrac{7}{3}$`, r`$\alpha^2 + \beta^2 = \dfrac{67}{9}$`, r`$\alpha^3 + \beta^3 = \dfrac{440}{27}$`], v: d2we2Tbl, n: 'The sum of the roots is five thirds and the product is minus seven thirds. The sum of squares is S squared minus two P, which is twenty five ninths plus fourteen thirds, sixty seven ninths. The sum of cubes is S cubed minus three P S, which is four hundred forty over twenty seven.' }),
    sl('check', 'Quick check: a cube sum', { b: 'Compute the sum of cubes of the roots of a given quadratic.', chk: 'n1', n: 'Find the sum and product first, then use the cube formula.' }),
    sl('concept', 'Roots that are functions of the roots', { b: r`To form the equation whose roots are, say, $\alpha^3$ and $\beta^3$, find the **new sum** and **new product** using symmetric functions.`, v: recipeFlow, n: 'The method never changes. Read the sum and product of the given equation. Write the new sum and the new product of the required roots using symmetric functions. Form x squared minus new sum times x plus new product. Clear fractions, and test one root.' }),
    sl('example', 'Worked example 3: cubes of the roots', { b: r`The roots of $x^2 - 4x + 2 = 0$ are $\alpha, \beta$. Form the equation with roots $\alpha^3, \beta^3$.`, ul: [r`$S = 4$, $P = 2$`, r`$\alpha^3 + \beta^3 = 64 - 24 = 40$, $\alpha^3\beta^3 = 8$`, '$x^2 - 40x + 8 = 0$'], v: d2we3Tbl, n: 'Here S is four and P is two. The new sum is S cubed minus three P S, which is sixty four minus twenty four, forty. The new product is P cubed, which is eight. So the equation with the cubes as roots is x squared minus forty x plus eight.' }),
    sl('example', 'Worked example 4: $\\alpha + \\dfrac{1}{\\beta}$ and $\\beta + \\dfrac{1}{\\alpha}$', { b: r`For $x^2 - 3x + 1 = 0$ form the equation with roots $\alpha + \dfrac{1}{\beta}$ and $\beta + \dfrac{1}{\alpha}$.`, ul: [r`New sum $= S + \dfrac{S}{P} = 6$`, r`New product $= P + 2 + \dfrac{1}{P} = 4$`, '$x^2 - 6x + 4 = 0$'], v: d2we4Tbl, n: 'The new sum is alpha plus beta plus the sum of the reciprocals, which is S plus S over P, three plus three, six. The new product has four terms, alpha beta plus one plus one plus one over alpha beta, which is four here. So the equation is x squared minus six x plus four.' }),
    sl('concept', 'Common roots', { b: 'Two quadratics have a **common root** $x_0$ when one number satisfies both. Eliminate $x^2$, solve the linear equation, and test.', v: commonFlow, n: 'If two equations share a root, that number satisfies both. Subtract suitable multiples to remove the x squared terms. What is left is a linear equation, and its solution is the only possible common root. Substitute it back to find the unknown, and always check it in both equations.' }),
    sl('example', 'Worked example 5: a common root', { b: r`Find the common root of $x^2 - 3x - 10 = 0$ and $2x^2 - 7x - 15 = 0$.`, ul: ['Double the first and subtract the second: $x - 5 = 0$', 'Common root $x = 5$', 'Check in both equations'], v: d2we5Tbl, n: 'Double the first equation to get two x squared minus six x minus twenty. Subtract the second equation and the x squared terms cancel, leaving x minus five equals zero. So the only possible common root is five, and substituting confirms that both equations vanish at five.' }),
    sl('diagram', 'Condition for a common root', { b: 'The elimination can be written as one relation between the six coefficients.', v: condFlow, n: 'Eliminating the common root between two quadratics gives one relation between their coefficients. It is c one a two minus c two a one, squared, equal to a one b two minus a two b one, times b one c two minus b two c one. If both roots are common, the coefficients are in proportion.' }),
    sl('check', 'Quick check: both roots common', { b: 'Decide whether two proportional equations share both roots.', chk: 'tf3', n: 'Compare the coefficients of the two equations.' }),
    sl('concept', 'The quadratic function', { b: r`For $f(x) = ax^2 + bx + c$ the graph is a parabola with axis $x = -\dfrac{b}{2a}$ and vertex $\left(-\dfrac{b}{2a},\ c - \dfrac{b^2}{4a}\right)$. It opens up if $a > 0$ (least value) and down if $a < 0$ (greatest value).`, v: pPar, n: 'The graph of a quadratic function is a parabola. Its axis is the vertical line through x equals minus b over two a, and the vertex is on that line. If a is positive the parabola opens upward and the vertex is the lowest point. If a is negative it opens downward and the vertex is the highest point.' }),
    sl('diagram', 'Sign of $ax^2 + bx + c$', { b: 'Combine the sign of $a$ with the number of real roots.', v: signTbl, n: 'The sign of the expression depends on two things: the sign of a and the discriminant. With two real roots and a positive, the expression is negative between the roots and positive outside. With a negative the pattern reverses. If the discriminant is zero, the sign never changes. If it is negative, the sign is that of a for every real x.' }),
    sl('check', 'Quick check: touching the axis', { b: 'Decide whether a perfect square parabola stays strictly above the axis.', chk: 'tf5', n: 'Find where the expression is zero.' }),
    sl('example', 'Worked example 6: greatest value and sign', { b: r`For $f(x) = -3x^2 + 12x - 7$ find the greatest value, the $y$-intercept and where $f(x) > 0$.`, ul: ['$f(x) = -3(x - 2)^2 + 5$: greatest value $5$ at $x = 2$', '$y$-intercept $-7$', r`$D = 60 > 0$, so $f > 0$ only between the roots $2 \pm \dfrac{\sqrt{15}}{3}$`], v: pF, n: 'Complete the square to get minus three times x minus two squared plus five. The bracket squared is never negative, so the function is at most five, and five is reached at x equal to two. At x equal to zero the value is minus seven. The discriminant is positive, so the function is positive only between its two roots.' }),
    sl('check', 'Quick check: a maximum', { b: 'Decide whether a downward parabola has a least value.', chk: 'tf4', n: 'Think about what happens far from the vertex.' }),
    sl('example', 'Worked example 7: the best rectangle', { b: r`A rectangle is fenced with $36$ m of wire. Find the width $x$ that gives the greatest area, and that area.`, ul: ['Length $= 18 - x$, so $A = x(18 - x) = -x^2 + 18x$', 'Greatest value at $x = 9$', '$A = 81$ m$^2$'], v: pA, n: 'With thirty six metres of wire, the length plus the width is eighteen. So the area is x times eighteen minus x, which is minus x squared plus eighteen x. This opens downward, so the greatest area is at x equal to nine, where it is eighty one square metres. The best rectangle is a square.' }),
    sl('check', 'Quick check: a least value', { b: 'Find the least value of an upward parabola.', chk: 'fb5', n: 'Complete the square.' }),
    sl('summary', 'Summary', { ul: [r`Equation from roots: $x^2 - Sx + P = 0$`, 'Symmetric functions through $S$ and $P$; roots $\\alpha^3, \\beta^3$ need $S^3 - 3PS$ and $P^3$', 'Common root: eliminate $x^2$, solve, substitute', r`Vertex $-\dfrac{b}{2a}$: greatest value if $a < 0$, least if $a > 0$`], v: summary2, n: 'To sum up. An equation is built from the sum and product of its roots. Symmetric functions are written with the sum and product. A common root comes from eliminating x squared, solving, and checking. And the vertex of a parabola gives the greatest value when a is negative and the least value when a is positive.' }),
    sl('exam-tips', 'Exam tips', { ul: ['Write $S$ and $P$ before the new sum and product', 'Check one new root in the formed equation', 'A common-root answer must satisfy **both** equations', 'For a word problem, say what the greatest value means in the context'], v: tips2, n: 'In the examination, write the sum and the product of the given roots first. Test one new root in the equation you formed. A common root must satisfy both equations. And in a word problem, say what the greatest or least value means for the situation, with its unit.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'isc-11-mathematics-ch06', version: 1, title: 'Quadratic Equations - chapter notes', language: 'en',
  sections: [
    { heading: '1. Roots, the fundamental theorem and the formula', body_md: r`A **quadratic equation** is $ax^2 + bx + c = 0$ with $a \ne 0$. The **fundamental theorem of algebra** (stated without proof) says that every polynomial equation of degree $n \ge 1$ with complex coefficients has at least one complex root, and hence exactly $n$ roots in $\mathbb{C}$ counted with multiplicity.\n\nThe roots are $x = \dfrac{-b \pm \sqrt{D}}{2a}$ with **discriminant** $D = b^2 - 4ac$. When $D < 0$, $\sqrt{D} = i\sqrt{-D}$, so the roots are non-real: for instance $3x^2 - 2x + 7 = 0$ gives $\dfrac{1 \pm 2i\sqrt{5}}{3}$.`, key_terms: [{ term: 'Discriminant', definition_md: '$D = b^2 - 4ac$; its sign decides the nature of the roots.' }, { term: 'Repeated root', definition_md: 'A root counted twice, as in $(x - 2)^2 = 0$.' }], formulas: [{ latex: r`x = \dfrac{-b \pm \sqrt{b^2 - 4ac}}{2a}`, label: 'Quadratic formula' }], visual: ftaTbl, visuals: [formulaFlow, we1Tbl], topic_ids: [topic(1)] },
    { heading: '2. Nature of the roots', body_md: r`For real coefficients: $D > 0$ gives two distinct real roots (rational if the coefficients are rational and $D$ is a perfect square, otherwise irrational); $D = 0$ gives two equal real roots $-\dfrac{b}{2a}$; $D < 0$ gives two non-real roots that are conjugates.\n\nWith **real** coefficients, non-real roots come in conjugate pairs $p \pm qi$. With **rational** coefficients, surd roots $m \pm \sqrt{n}$ come in pairs. With only real coefficients there is no such guarantee: $x^2 - (3 + \sqrt{3})x + (2 + \sqrt{3}) = 0$ has roots $2 + \sqrt{3}$ and $1$.`, key_terms: [{ term: 'Conjugate pair', definition_md: 'Roots $p + qi$ and $p - qi$, or $m + \\sqrt{n}$ and $m - \\sqrt{n}$.' }], formulas: [{ latex: r`D > 0,\ D = 0,\ D < 0`, label: 'Cut, touch, miss' }], visual: natureTbl, visuals: [pCases, conjTbl, we2Tbl], topic_ids: [topic(3)] },
    { heading: '3. Sum and product of the roots; special conditions', body_md: r`If $\alpha, \beta$ are the roots of $ax^2 + bx + c = 0$ then $\alpha + \beta = -\dfrac{b}{a}$ and $\alpha\beta = \dfrac{c}{a}$.\n\nSpecial roots: equal $b^2 = 4ac$; reciprocal $c = a$; equal and opposite $b = 0$; one root zero $c = 0$; one twice the other $2b^2 = 9ac$; one the square of the other $ac^2 + a^2c + b^3 = 3abc$. A condition on a parameter may need a second check, such as $D > 0$ for real roots.`, key_terms: [{ term: 'Reciprocal roots', definition_md: 'Roots with product $1$: the condition is $c = a$.' }], formulas: [{ latex: r`\alpha + \beta = -\dfrac{b}{a},\quad \alpha\beta = \dfrac{c}{a}`, label: 'Sum and product' }, { latex: r`ac^2 + a^2c + b^3 = 3abc`, label: 'One root the square of the other' }], visual: condTbl, visuals: [spFlow, we5Tbl, we6Tbl], topic_ids: [topic(3)] },
    { heading: '4. Equations reducible to quadratic form', body_md: r`Give a repeated expression a new letter. For $ax^4 + bx^2 + c = 0$ put $y = x^2$; for a repeated bracket put $y$ equal to the bracket; for a palindromic equation divide by $x^2$ and put $y = x + \dfrac{1}{x}$, using $x^2 + \dfrac{1}{x^2} = y^2 - 2$.\n\nSolve the quadratic in $y$, then solve **each** equation $x^2 = y$ (or $x + \dfrac{1}{x} = y$). Negative values of $y$ in $y = x^2$ give non-real $x$; for example $x^4 + 2x^2 - 15 = 0$ has the roots $\pm\sqrt{3}$ and $\pm i\sqrt{5}$.`, key_terms: [{ term: 'Substitution', definition_md: 'A new letter for a repeated expression, so that the equation becomes a quadratic.' }], formulas: [{ latex: r`x^2 + \dfrac{1}{x^2} = \left(x + \dfrac{1}{x}\right)^2 - 2`, label: 'Palindromic equations' }], visual: redTbl, visuals: [we3Tbl, we4Tbl], topic_ids: [topic(2)] },
    { heading: '5. Forming equations; symmetric functions of the roots', body_md: r`The equation with roots $\alpha, \beta$ is $x^2 - (\alpha + \beta)x + \alpha\beta = 0$, multiplied through to clear fractions.\n\nWith $S = \alpha + \beta$ and $P = \alpha\beta$: $\alpha^2 + \beta^2 = S^2 - 2P$; $\alpha^3 + \beta^3 = S^3 - 3PS$; $(\alpha - \beta)^2 = S^2 - 4P$; $\dfrac{1}{\alpha} + \dfrac{1}{\beta} = \dfrac{S}{P}$; $\alpha^2\beta + \alpha\beta^2 = PS$.`, key_terms: [{ term: 'Symmetric function', definition_md: 'An expression unchanged when $\\alpha$ and $\\beta$ are swapped; it can be written with $S$ and $P$.' }], formulas: [{ latex: r`x^2 - Sx + P = 0`, label: 'Equation from its roots' }, { latex: r`\alpha^3 + \beta^3 = S^3 - 3PS`, label: 'Sum of cubes' }], visual: formTbl, visuals: [symTbl, d2we2Tbl], topic_ids: [topic(4)] },
    { heading: '6. Roots that are functions of the roots; common roots', body_md: r`To form the equation whose roots are $f(\alpha)$ and $f(\beta)$: write the new sum and the new product through $S$ and $P$, then use $x^2 - S_1x + P_1 = 0$. For $\alpha^3, \beta^3$: $S_1 = S^3 - 3PS$ and $P_1 = P^3$. For $\alpha + \dfrac{1}{\beta}$ and $\beta + \dfrac{1}{\alpha}$: $S_1 = S + \dfrac{S}{P}$ and $P_1 = P + 2 + \dfrac{1}{P}$.\n\n**Common root:** subtract suitable multiples of the two equations to remove $x^2$, solve the linear equation for the common root, substitute to find the unknown, and check in both equations. One common root needs $(c_1a_2 - c_2a_1)^2 = (a_1b_2 - a_2b_1)(b_1c_2 - b_2c_1)$; both roots common needs proportional coefficients.`, key_terms: [{ term: 'Common root', definition_md: 'A number that satisfies two different equations at once.' }], formulas: [{ latex: r`(c_1a_2 - c_2a_1)^2 = (a_1b_2 - a_2b_1)(b_1c_2 - b_2c_1)`, label: 'One common root' }], visual: recipeFlow, visuals: [d2we3Tbl, d2we4Tbl, commonFlow, d2we5Tbl], topic_ids: [topic(4)] },
    { heading: '7. Quadratic functions: sign, graph, greatest and least values', body_md: r`The graph of $f(x) = ax^2 + bx + c$ is a parabola with axis $x = -\dfrac{b}{2a}$ and vertex $\left(-\dfrac{b}{2a},\ c - \dfrac{b^2}{4a}\right)$. It opens up for $a > 0$ (least value at the vertex) and down for $a < 0$ (greatest value at the vertex).\n\nSign: for $a > 0$ and $D > 0$ the expression is negative between the roots and positive outside; for $a < 0$ it reverses; for $D = 0$ it keeps one sign and touches zero once; for $D < 0$ it has the sign of $a$ for all real $x$. To sketch: vertex, axis, $y$-intercept $c$ and any real $x$-intercepts.`, key_terms: [{ term: 'Vertex', definition_md: 'The turning point of a parabola, at $x = -\\dfrac{b}{2a}$.' }, { term: 'Axis', definition_md: 'The vertical line through the vertex; the graph is symmetric about it.' }], formulas: [{ latex: r`f_{\min/\max} = c - \dfrac{b^2}{4a}\ \text{at}\ x = -\dfrac{b}{2a}`, label: 'Extreme value' }], visual: pPar, visuals: [signTbl, pF, pA], topic_ids: [topic(5)] },
  ],
  exam_tips_md: r`**How ISC marks are usually awarded**\n- *Solving with complex roots (2-3 marks):* the discriminant, the simplified surd, then the roots.\n- *Nature of roots or a parameter (2-3 marks):* the discriminant in the parameter, the condition solved, the value.\n- *Reducible equations (2-3 marks):* the substitution, the values of the new letter, every root in $x$.\n- *Forming equations (2-3 marks):* the sum and product of the given roots, the new sum and product, the equation.\n- *Common roots (3 marks):* the elimination, the common root, the unknown.\n- *Quadratic functions (3 marks):* the vertex, the value, intercepts or a sign statement.\n- *Section D (5 marks):* questions come in parts such as 1 + 1 + 1 + 2; label each part.\n\n**Common mistakes**\n- Forgetting to divide by $2a$, or halving only part of the numerator.\n- Writing $\sqrt{-24} = 24i$ instead of $2i\sqrt{6}$.\n- Dropping the roots from $x^2 = y$ when $y$ is negative (they are non-real, not absent).\n- Assuming $m - \sqrt{n}$ is a root when the coefficients are only real.\n- Using $S^3 + 3PS$ for $\alpha^3 + \beta^3$.\n- Giving a common root without testing it in both equations.`,
  status: 'draft', provenance: d1.provenance,
};

